package com.lamggm.rospocket;
import java.util.*;import org.json.*;
/** Bounded latest-common-time TF. ROS timestamps never use the phone wall clock. */
final class RobotTf {
 static final long MAX_AGE_NS=2000000000L;
 static final class Pose {final boolean live;final String status;final long stamp,revision,deadline;final Map<String,double[]> transforms;Pose(boolean l,String s,long t,long r,Map<String,double[]> m){this(l,s,t,r,m,Long.MAX_VALUE);}Pose(boolean l,String s,long t,long r,Map<String,double[]> m,long expiry){live=l;status=s;stamp=t;revision=r;deadline=expiry;transforms=Collections.unmodifiableMap(new LinkedHashMap<>(m));}}
 private static final class Edge {final String parent,child,writer;final long stamp,received;final boolean fixed;final double[] matrix;Edge(JSONObject j,long now)throws Exception{parent=frame(j.getString("parent"));child=frame(j.getString("child"));writer=j.getString("writer");Object st=j.get("stamp"),fix=j.get("static");if(!(st instanceof Integer||st instanceof Long)||!(fix instanceof Boolean)||writer.isEmpty()||writer.length()>256||parent.equals(child))throw new IllegalArgumentException("TF inválido");stamp=((Number)st).longValue();fixed=(Boolean)fix;received=now;if(stamp<0||!fixed&&stamp==0)throw new IllegalArgumentException("Timestamp TF inválido");double[] t=vec(j.getJSONArray("translation"),3),q=vec(j.getJSONArray("rotation"),4);double x=q[0],y=q[1],z=q[2],w=q[3],norm=x*x+y*y+z*z+w*w;if(Math.abs(norm-1)>.001)throw new IllegalArgumentException("Quaternion TF inválido");double n=Math.sqrt(norm);x/=n;y/=n;z/=n;w/=n;matrix=new double[]{1-2*y*y-2*z*z,2*x*y-2*z*w,2*x*z+2*y*w,t[0],2*x*y+2*z*w,1-2*x*x-2*z*z,2*y*z-2*x*w,t[1],2*x*z-2*y*w,2*y*z+2*x*w,1-2*x*x-2*y*y,t[2],0,0,0,1};}}
 private final Map<String,ArrayDeque<Edge>> history=new LinkedHashMap<>();private String error="";private boolean conflict;private long revision;
 private static String frame(String v){if(v.isEmpty()||v.length()>256||v.startsWith("/")||v.chars().anyMatch(c->Character.isWhitespace(c)||Character.isISOControl(c)))throw new IllegalArgumentException("Frame TF inválido");return v;}
 private static double[] vec(JSONArray a,int n)throws Exception{if(a.length()!=n)throw new IllegalArgumentException("Vetor TF inválido");double[] out=new double[n];for(int i=0;i<n;i++){Object v=a.get(i);if(!(v instanceof Number))throw new IllegalArgumentException("Vetor TF inválido");out[i]=((Number)v).doubleValue();if(!Double.isFinite(out[i])||Math.abs(out[i])>1e6)throw new IllegalArgumentException("Vetor TF inválido");}return out;}
 void accept(JSONArray rows,long received){
  if(rows==null||rows.length()>512||received<0){error="TF fora dos limites";return;}if(conflict)return;
  try{List<Edge> incoming=new ArrayList<>();for(int i=0;i<rows.length();i++)incoming.add(new Edge(rows.getJSONObject(i),received));if(!incoming.isEmpty())error="";
   for(Edge e:incoming){ArrayDeque<Edge> h=history.get(e.child);Edge last=h==null?null:h.peekLast();if(last!=null&&(!last.parent.equals(e.parent)||!last.writer.equals(e.writer)||last.fixed!=e.fixed)){conflict=true;throw new IllegalArgumentException("TF com autoridades/pais ambíguos · reconecte");}if(last!=null&&!e.fixed){if(e.stamp<last.stamp){error="Timestamp TF regressivo · reconecte se o relógio ROS reiniciou";continue;}if(e.stamp==last.stamp){if(!Arrays.equals(e.matrix,last.matrix))error="TF contraditório no mesmo timestamp";continue;}}
    if(last!=null&&e.fixed&&Arrays.equals(last.matrix,e.matrix))continue;if(h==null){if(history.size()>=256)throw new IllegalArgumentException("Limite de frames TF excedido");h=new ArrayDeque<>();history.put(e.child,h);}if(e.fixed)h.clear();h.addLast(e);while(h.size()>32)h.removeFirst();revision++;
   }
  }catch(Exception e){error=e.getMessage()==null?"TF inválido":e.getMessage();}
 }
 private Pose unavailable(String reason){return new Pose(false,reason,0,revision,Collections.emptyMap());}
 Pose solve(String fixed,Set<String> links,long now){
  if(!error.isEmpty())return unavailable(error);if(history.isEmpty())return unavailable("Aguardando TF observado · frame fixo "+fixed);if(links.size()>128)return unavailable("Limite de links TF");boolean known=false;for(ArrayDeque<Edge> h:history.values()){Edge e=h.peekLast();if(e.parent.equals(fixed)||e.child.equals(fixed))known=true;}if(!known)return unavailable("Frame fixo TF não observado: "+fixed);
  try{frame(fixed);Set<String> checked=new HashSet<>();for(String start:history.keySet()){String cursor=start;Set<String> chain=new HashSet<>();while(history.containsKey(cursor)&&!checked.contains(cursor)){if(!chain.add(cursor))return unavailable("Ciclo na árvore TF");cursor=history.get(cursor).peekLast().parent;}checked.addAll(chain);}Map<String,List<ArrayDeque<Edge>>> paths=new LinkedHashMap<>();long common=Long.MAX_VALUE;
   for(String link:links){List<ArrayDeque<Edge>> path=new ArrayList<>();Set<String> seen=new HashSet<>();String current=link;while(!current.equals(fixed)){if(!seen.add(current)||seen.size()>128)return unavailable("Ciclo na árvore TF");ArrayDeque<Edge> h=history.get(current);if(h==null)return unavailable("TF ausente: "+current+" · frame fixo "+fixed);Edge e=h.peekLast();if(!e.fixed){if(now<e.received||now-e.received>MAX_AGE_NS)return unavailable("TF atrasado: "+current);common=Math.min(common,e.stamp);}path.add(h);current=e.parent;}paths.put(link,path);}
   long deadline=Long.MAX_VALUE;Map<String,double[]> transforms=new LinkedHashMap<>();for(Map.Entry<String,List<ArrayDeque<Edge>>> item:paths.entrySet()){double[] matrix=RobotDescription.identity();List<ArrayDeque<Edge>> path=item.getValue();for(int i=path.size()-1;i>=0;i--){Edge selected=null;for(Edge e:path.get(i))if(e.fixed||e.stamp<=common)selected=e;if(selected==null||!selected.fixed&&(now<selected.received||now-selected.received>MAX_AGE_NS))return unavailable("Sem intervalo TF comum recente");if(!selected.fixed)deadline=Math.min(deadline,Math.addExact(selected.received,MAX_AGE_NS));matrix=RobotDescription.multiply(matrix,selected.matrix);}transforms.put(item.getKey(),matrix);}long stamp=common==Long.MAX_VALUE?0:common;return new Pose(true,(stamp==0?"TF estático observado":"TF observado · t="+stamp/1000000000d)+" · frame fixo "+fixed,stamp,revision,transforms,deadline);
  }catch(Exception e){return unavailable("Árvore TF inválida");}
 }
}
